-- =====================================================================
-- แถวที่ sql/_backfill/20260916_echo_duplicates.sql ลบออก — เอากลับคืนได้จากไฟล์นี้
-- =====================================================================
-- ดึงจากโปรดักชันก่อนลง backfill (2026-09-16) ด้วย pg_get แบบประกอบ insert เอง
-- ★ ทุกคำสั่งมี on conflict do nothing — กู้คืนซ้ำได้ไม่พัง
-- ★ ลำดับสำคัญ: message ต้องมาก่อน reply_sample (FK message_id) และก่อน
--   human_reply_events ไม่จำเป็นต้องมี message แต่เรียงตามนี้ไว้จะปลอดภัยที่สุด
-- ★ ถ้ากู้คืนแล้ว ต้องล้าง external_message_id ของ "แถวต้นฉบับ" ด้วย ไม่งั้นชน
--   unique (conversation_id, external_message_id) — คำสั่งอยู่ท้ายไฟล์
--
-- วิธีใช้:  psql -U postgres -d postgres -v ON_ERROR_STOP=1 -f <ไฟล์นี้>
-- =====================================================================

begin;

-- ── ขั้นแรก: ถอด mid ออกจากแถวต้นฉบับก่อน ─────────────────────────────
-- ★ ต้องมาก่อน insert เสมอ ไม่งั้นชน unique (conversation_id, external_message_id)
--   เพราะ backfill ย้าย mid ไปไว้ที่แถวต้นฉบับแล้ว
update inbox.message m
   set external_message_id = null
 where m.id in ('6bedf9f1-ea5d-48a7-9883-26457a7842f9'::uuid, 'e2e5b98f-7d42-4019-931c-8ce5e884244d'::uuid, 'c1f52cd5-c058-4b31-ab27-f026ad786346'::uuid, '3fd20d73-6d4d-4d17-ab25-20f7cb0e625a'::uuid, '6874c110-601d-41af-9546-e7890210ce46'::uuid, '67447c29-2785-4e86-a1f0-7cef698fb099'::uuid, 'c888121b-96d8-471e-b8e7-51bb1d3a60b6'::uuid, '15ac6550-98a4-4dfd-a690-37ad838be299'::uuid)
   and m.external_message_id is not null;






commit;
